def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    last_me, last_opp = history[-1]
    prev_me, prev_opp = history[-2]
    def opp_coop_rate():
        c = 0
        for _, o in history:
            if o == 'C':
                c += 1
        return c / n
    def my_coop_rate():
        c = 0
        for m, _ in history:
            if m == 'C':
                c += 1
        return c / n
    oc = opp_coop_rate()
    mc = my_coop_rate()
    streak_c = 0
    streak_d = 0
    for m, o in reversed(history):
        if o == 'C' and streak_d == 0:
            streak_c += 1
        elif o == 'D' and streak_c == 0:
            streak_d += 1
        else:
            break
    if last_opp == 'D' and prev_opp == 'D' and streak_d >= 2:
        if streak_d >= 4:
            return 'C'
        return 'D'
    if oc > 0.85 and mc > 0.85:
        return 'C'
    if last_opp == 'D':
        if n > 10 and oc > 0.5:
            return 'D'
        if rng.random() < 0.35:
            return 'D'
        return 'C'
    if last_opp == 'C' and prev_opp == 'D' and last_me == 'D':
        return 'D'
    if oc < 0.2:
        return 'D'
    if oc < 0.35:
        if rng.random() < 0.6:
            return 'D'
        return 'C'
    if n > 90:
        if oc > 0.6:
            return 'C'
        return 'D'
    if last_opp == 'C' and last_me == 'C':
        if rng.random() < 0.08:
            return 'D'
        return 'C'
    return 'C'

